def _half(text: str, first: bool) -> str:
    """First or second half of a text, split at the sentence nearest the middle."""
    sents = __import__("re").split(r"(?<=[.!?])\s+", text)
    total, run, cut = len(text.split()), 0, 0
    for i, s in enumerate(sents):
        if abs(run + len(s.split()) - total / 2) > abs(run - total / 2):
            break
        run, cut = run + len(s.split()), i + 1
    return " ".join(sents[:cut] if first else sents[cut:])


